input.newString:
// Copy the expression token to use as the matcher name token so that it
// inherits the same file, line, and import context. This is important for
// tokens that come from snippets, since the dispenser uses the import
// context to determine whether two tokens are on the same line.
matcherNameToken := d.Token()
matcherNameToken.Text = "expression"

tokens := []caddyfile.Token{
	matcherNameToken,
	d.Token(),
}
st.namedMatchers.pendingTokens = tokens
return tokens
